const data = $input.first().json;

const emaCurrent = data.ema_current_status || 'UNKNOWN';
const emaPrev = data.ema_prev_status || 'UNKNOWN';
const actCurrent = data.act_current_status || 'UNKNOWN';
const actOfflineSeconds = data.act_offline_seconds || 0;

const now = new Date().getTime();
const emaChangeTime = data.ema_current_time ? new Date(data.ema_current_time).getTime() : 0;
// Verificar si el cambio ocurrió en los últimos 3 minutos
const isEmaNewChange = (now - emaChangeTime) <= 180000 && emaCurrent !== emaPrev;

let alertType = 'NONE';
let message = '';

// CASO A: Sin Conexión WiFi (Apagón General / El Actuador ya llevaba >= 5 min OFFLINE)
if (emaCurrent === 'OFFLINE' && actCurrent === 'OFFLINE' && actOfflineSeconds >= 300) {
  if (isEmaNewChange) {
    alertType = 'SIN_CONEXION_WIFI';
    message = '**Sin Conexión WiFi**\n\nNodo EMA: Offline\nNodo Actuador: Offline';
  }
}
// CASO B: Batería Agotada (Nodo EMA OFFLINE por batería mientras Actuador está bien)
else if (emaCurrent === 'OFFLINE' && (actCurrent !== 'OFFLINE' || actOfflineSeconds < 300)) {
  if (isEmaNewChange) {
    alertType = 'BATERIA_AGOTADA';

    // Cálculo exacto de duración de batería
    let durationText = 'Desconocida';
    if (data.ema_current_time && data.ema_cycle_start_time) {
      const cycleStart = new Date(data.ema_cycle_start_time).getTime();
      const cycleEnd = new Date(data.ema_current_time).getTime();
      const diffMs = cycleEnd - cycleStart;

      if (diffMs > 0) {
        const totalMinutes = Math.floor(diffMs / (1000 * 60));
        const days = Math.floor(totalMinutes / (60 * 24));
        const hours = Math.floor((totalMinutes % (60 * 24)) / 60);
        const mins = totalMinutes % 60;

        let parts = [];
        if (days > 0) parts.push(`${days}d`);
        if (hours > 0) parts.push(`${hours}h`);
        if (mins > 0 || parts.length === 0) parts.push(`${mins}min`);
        durationText = parts.join(' ');
      }
    }

    message = `**Batería Agotada**\nNodo EMA: Offline.\nDuración: ${durationText}`;
  }
}
// CASO C: Restablecimiento del Nodo EMA (Transición de OFFLINE -> ONLINE/SLEEP tras cambio de batería)
else if ((emaCurrent === 'ONLINE' || emaCurrent === 'SLEEP') && emaPrev === 'OFFLINE') {
  if (isEmaNewChange && actOfflineSeconds < 300) {
    alertType = 'EMA_RESTABLECIDO';
    message = '**Nodo EMA**\nOperativo.';
  }
}

if (alertType === 'NONE') {
  return [];
}

return [{ json: { alertType, message } }];
